'use strict';

// MODULES //

var isAsci = require( '@stdlib/assert/is-ascii' );
var isValidRowCol = require( './utils/is-valid-row-col.js' );

/**
* Method to draw the bar.
*
* @private
* @name addString
* @param {number} row - row number
* @param {number} col - col number
* @param {string} value - value
* @param {boolean} overwrite - overwrite
* @returns {void}
*/
function addString( row, col, value, overwrite ) {
	var cond1;
	var cond2;
	var chr;
	var r;
	var c;
	var i;

	r = row;
	c = col;
	for ( i = 0; i < value.length; i++ ) {
		chr = value[ i ];
		cond1 = isValidRowCol( r, c, this._height, this._width );
		cond2 = ( overwrite || this._glyphMatrix[ r ][ c ] === this._glyph );
		if ( isAsci( chr ) && cond1 && cond2 ) {
			this.setGlyph( r, c, 'asci' + chr.charCodeAt( 0 ), overwrite );
		}
		c+=1;
	}
}

module.exports = addString;
